import unittest
from candidate import is_palindrome

class TestPalindrome(unittest.TestCase):
    def test_empty_string(self):
        self.assertTrue(is_palindrome(''))

    def test_single_character(self):
        self.assertTrue(is_palindrome('a'))

    def test_palindrome_string(self):
        self.assertTrue(is_palindrome('aba'))

    def test_long_palindrome_string(self):
        self.assertTrue(is_palindrome('aaaaa'))

    def test_non_palindrome_string(self):
        self.assertFalse(is_palindrome('zbcd'))

    def test_string_with_spaces(self):
        self.assertTrue(is_palindrome('a b a'))

    def test_string_with_punctuation(self):
        self.assertTrue(is_palindrome('a,b,a'))

    def test_string_with_mixed_case(self):
        self.assertTrue(is_palindrome('Aba'))

    def test_none_input(self):
        with self.assertRaises(TypeError):
            is_palindrome(None)

    def test_non_string_input(self):
        with self.assertRaises(TypeError):
            is_palindrome(123)

if __name__ == '__main__':
    unittest.main()
